namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes over dough.", "Add torn mozzarella pieces.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 52
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy pasta with pancetta, eggs, and Pecorino Romano.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture quickly.", "Serve immediately with extra cheese."],
                TotalRatings = 8, RatingSum = 36
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and spices, simmer 15 minutes.", "Stir in cream and cooked chicken.", "Serve over basmati rice."],
                TotalRatings = 15, RatingSum = 70
            },
            new()
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "A tangy, sweet, and savory stir-fried noodle dish.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Sugar", "Eggs"],
                Steps = ["Soak rice noodles in warm water for 30 minutes.", "Mix tamarind paste, fish sauce, and sugar for the sauce.", "Fry tofu until golden.", "Scramble eggs in the wok.", "Add noodles and sauce, toss together.", "Garnish with peanuts, bean sprouts, and lime."],
                TotalRatings = 6, RatingSum = 25
            },
            new()
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry skillet.", "Fill tortillas with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa.", "Serve immediately."],
                TotalRatings = 10, RatingSum = 43
            },
            new()
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Salt", "Tomato"],
                Steps = ["Mash avocados in a bowl.", "Stir in lime juice, diced onion, jalapeño, and cilantro.", "Fold in diced tomato.", "Season with salt to taste.", "Serve with tortilla chips."],
                TotalRatings = 9, RatingSum = 40
            },
            new()
            {
                Id = 7, Title = "Miso Ramen", Category = "Asian",
                Description = "Rich miso broth with noodles, soft-boiled egg, and toppings.",
                Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Soft-boiled eggs", "Green onions", "Corn", "Nori"],
                Steps = ["Bring chicken broth to a simmer.", "Whisk in miso paste and soy sauce.", "Cook ramen noodles separately.", "Divide noodles into bowls, ladle broth over.", "Top with halved soft-boiled egg, corn, green onions, and nori.", "Serve hot."],
                TotalRatings = 11, RatingSum = 49
            },
            new()
            {
                Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual cakes with a warm, gooey chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk in eggs, sugar, and vanilla.", "Fold in flour.", "Pour into greased ramekins.", "Bake for 12-14 minutes until edges are firm but center is soft.", "Invert onto plates and serve immediately."],
                TotalRatings = 14, RatingSum = 65
            },
        ];
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}

